private.reference_solution:
var line = Console.ReadLine() ?? "";
if (int.TryParse(line, out var number))
{
    if (number >= 1 && number <= 3)
    {
        Console.WriteLine(((Level)number).ToString());
    }
    else
    {
        Environment.Exit(1);
    }
    return;
}
if (Enum.TryParse(line, out Level parsed) && line == parsed.ToString())
{
    Console.WriteLine((int)parsed);
    return;
}
Environment.Exit(1);

enum Level
{
    Low = 1,
    Medium = 2,
    High = 3
}
